<?php
namespace App\Http\Controllers\Tenant;
use App\Domain\AI\Agents\Models\Agent;use App\Domain\AI\Channels\WhatsApp\Models\WhatsAppChannel;use App\Domain\AI\Channels\WhatsApp\Services\ManageWhatsAppChannelService;use App\Http\Controllers\Controller;use App\Http\Support\AiLaunchpadHttpGate;use Illuminate\Http\Request;
final class AiWhatsAppController extends Controller{
 public function show(Request$r,Agent$agent,AiLaunchpadHttpGate$gate,AiTenantBoundary$tenants){$gate->ensure($r->user());$gate->assertCurrentTenant($agent);$channel=WhatsAppChannel::where('tenant_id',$agent->tenant_id)->where('agent_id',$agent->id)->first();return view('tenant.admin.ai-agents.whatsapp',['tenant'=>$tenants->requireTenant(),'agent'=>$agent,'channel'=>$channel,'newVerifyToken'=>session('new_whatsapp_verify_token')]);}
 public function save(Request$r,Agent$agent,AiLaunchpadHttpGate$gate,ManageWhatsAppChannelService$s){$gate->ensure($r->user());$gate->assertCurrentTenant($agent);$d=$r->validate(['enabled'=>['nullable','boolean'],'phone_number_id'=>['required','string','max:120','regex:/^[A-Za-z0-9_-]+$/'],'business_account_ref'=>['nullable','string','max:120'],'display_phone'=>['nullable','string','max:40'],'access_token'=>['nullable','string','max:4096'],'app_secret'=>['nullable','string','max:4096'],'rotate_verify_token'=>['nullable','boolean']]);$d['enabled']=$r->boolean('enabled');$d['rotate_verify_token']=$r->boolean('rotate_verify_token');try{[$channel,$verify]=$s->save($r->user(),$agent,$d);}catch(\DomainException|\InvalidArgumentException){return back()->withErrors(['whatsapp'=>'No fue posible guardar una configuración operativa.']);}$redirect=redirect()->route('tenant.admin.ai-agents.whatsapp.show',$agent)->with('success','Canal actualizado.');return$verify?$redirect->with('new_whatsapp_verify_token',$verify):$redirect;}
}
